head.script:
scwin.trigger1_onclick = function(e) {
    var v = dataMap1.get("key1");
    alert(v);
    console.log(v);
    WebSquare.logger.printLog(v);
    //alert(v);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (scwin.$w.widget) {
        dataMap1.set("key1", scwin.$w.widget.getWidgetId());
        trigger1.setValue(scwin.$w.widget.getWidgetId());
    } else {
        dataMap1.set("key1", "widget아님");
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
